import{_ as e,o as l,c as a,a2 as n}from"./chunks/framework.BWuWLRhz.js";const x=JSON.parse('{"title":"対応ファイルマネージャーとダイアログ統合","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/file-manager-support.md","filePath":"ja-JP/user-guide/file-manager-support.md","lastUpdated":1787586465000}'),d={name:"ja-JP/user-guide/file-manager-support.md"};function r(s,t,i,o,g,f){return l(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="対応ファイルマネージャーとダイアログ統合" tabindex="-1">対応ファイルマネージャーとダイアログ統合 <a class="header-anchor" href="#対応ファイルマネージャーとダイアログ統合" aria-label="Permalink to &quot;対応ファイルマネージャーとダイアログ統合&quot;">​</a></h1><p>Lertaro は単体のデスクトップランチャーにとどまらず、Windows エクスプローラー、サードパーティ製ファイラー、各種アプリのダイアログに深く組み込まれ、ファイルを開く・保存する・フォルダーを移動する作業を劇的に効率化します。</p><h2 id="_1-3-つの主要な統合機能" tabindex="-1">1. 3 つの主要な統合機能 <a class="header-anchor" href="#_1-3-つの主要な統合機能" aria-label="Permalink to &quot;1. 3 つの主要な統合機能&quot;">​</a></h2><p>対象となるウィンドウの特性に応じて、最大 3 つの統合機能が提供されます。</p><ul><li><strong>インライン検索（Inline Search）</strong>：対象ウィンドウの上部やダイアログ内に検索バーを直接埋め込み、作業中の画面を離れることなく現在のフォルダーや全体を即座に検索。</li><li><strong>クイックナビゲーション（Quick Navigation）</strong>：余白の中クリック（またはダブルクリック）やロゴのクリックで、現在開いているフォルダー、お気に入り、履歴、カスタム分類を含む階層メニューを表示。</li><li><strong>アクティブパス検知（Active Path Detection）</strong>：対象ウィンドウが現在開いているフォルダーをリアルタイムに検知し、検索範囲を自動的にそのフォルダーに限定したり、相対パス操作を正確に解決。</li></ul><h2 id="_2-windows-標準コンポーネント-組み込み・設定不要" tabindex="-1">2. Windows 標準コンポーネント（組み込み・設定不要） <a class="header-anchor" href="#_2-windows-標準コンポーネント-組み込み・設定不要" aria-label="Permalink to &quot;2. Windows 標準コンポーネント（組み込み・設定不要）&quot;">​</a></h2><p>以下の標準コンポーネントは、追加のプラグインなしで標準でサポートされています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">対象ウィンドウ</th><th style="text-align:left;">インライン検索</th><th style="text-align:left;">クイックナビゲーション操作</th><th style="text-align:left;">アクティブパス検知</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows エクスプローラー</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">余白部分で左ダブルクリックまたは中クリック</td><td style="text-align:left;">対応</td></tr><tr><td style="text-align:left;"><strong>モダン「開く/保存」ダイアログ</strong></td><td style="text-align:left;">対応（ダイアログ内に直接埋め込み）</td><td style="text-align:left;">中クリック、またはロゴアイコンを左クリック</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>クラシック「開く/保存」ダイアログ</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンを左クリック</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>フォルダーの参照ダイアログ</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンを左クリック</td><td style="text-align:left;">—</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>各種ファイル選択ダイアログでは、Lertaro がダイアログ内部に直接埋め込まれているため、外部からのパス検知は不要です。クイックナビゲーションで項目を選択すると、ダイアログがそのフォルダーへ直接移動します。</p></div><h2 id="_3-サードパーティ製ファイラー対応-プラグイン" tabindex="-1">3. サードパーティ製ファイラー対応（プラグイン） <a class="header-anchor" href="#_3-サードパーティ製ファイラー対応-プラグイン" aria-label="Permalink to &quot;3. サードパーティ製ファイラー対応（プラグイン）&quot;">​</a></h2><p>高度なファイラーをご利用の方向けに、専用の統合プラグインが用意されています。<a href="./settings/plugins.html"><strong>設定 → プラグイン</strong></a> で有効化し、インライン検索やクイックナビゲーションを個別に設定できます。</p><table tabindex="0"><thead><tr><th style="text-align:left;">ファイラー名</th><th style="text-align:left;">インライン検索</th><th style="text-align:left;">クイックナビゲーション操作</th><th style="text-align:left;">アクティブパス検知</th><th style="text-align:left;">通信方式・プロトコル</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Directory Opus</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">ファイル一覧領域で中クリック</td><td style="text-align:left;">対応</td><td style="text-align:left;"><code>WM_COPYDATA</code> 公式リモート API</td></tr><tr><td style="text-align:left;"><strong>Total Commander</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">ファイル一覧領域で中クリック</td><td style="text-align:left;">対応</td><td style="text-align:left;"><code>WM_COPYDATA</code> 公式メッセージプロトコル</td></tr><tr><td style="text-align:left;"><strong>XYplorer</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">ファイル一覧領域で中クリック</td><td style="text-align:left;">対応</td><td style="text-align:left;">専用プロセス間通信</td></tr><tr><td style="text-align:left;"><strong>Files</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">ファイル一覧領域で中クリック</td><td style="text-align:left;">対応</td><td style="text-align:left;">Windows UI Automation</td></tr><tr><td style="text-align:left;"><strong>One Commander</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">ファイル一覧領域で中クリック</td><td style="text-align:left;">対応</td><td style="text-align:left;">Windows UI Automation</td></tr></tbody></table><h3 id="directory-opus-向けの高度な統合" tabindex="-1">Directory Opus 向けの高度な統合 <a class="header-anchor" href="#directory-opus-向けの高度な統合" aria-label="Permalink to &quot;Directory Opus 向けの高度な統合&quot;">​</a></h3><ul><li><strong>フォルダーサイズ列（Lertaro サイズ）</strong>：Directory Opus プラグインで「Lertaro サイズ列を有効化」にすると、カスタムスクリプト列が追加されます。Lertaro のインメモリインデックスから再帰的な合計サイズを直接取得するため、<strong>ディスク I/O ゼロ</strong> でドライブ全体のフォルダーサイズを瞬時に表示できます。</li><li><strong>設定の保存</strong>：列セレクターで「Lertaro サイズ」を追加後、<strong>フォルダー → フォルダー形式 → 保存 → すべてのフォルダーに形式を保存</strong> をクリックして永続化します。</li></ul><h3 id="everything-互換サービス-ipc" tabindex="-1">Everything 互換サービス (IPC) <a class="header-anchor" href="#everything-互換サービス-ipc" aria-label="Permalink to &quot;Everything 互換サービス (IPC)&quot;">​</a></h3><p><a href="./settings/general.html#システム"><strong>設定 → 一般 → システム</strong></a> で <strong>Everything 互換サービス (IPC) を有効化</strong> すると、標準の Everything Win32 IPC インターフェースをエミュレートします。Directory Opus、Total Commander、Flow Launcher などのツールから、Everything を起動することなく Lertaro のインメモリインデックスを直接利用できます。</p><h2 id="_4-各種アプリの独自ダイアログ対応-専用プラグイン" tabindex="-1">4. 各種アプリの独自ダイアログ対応（専用プラグイン） <a class="header-anchor" href="#_4-各種アプリの独自ダイアログ対応-専用プラグイン" aria-label="Permalink to &quot;4. 各種アプリの独自ダイアログ対応（専用プラグイン）&quot;">​</a></h2><p>標準の Windows ダイアログを使用せず、独自のカスタムダイアログを持つ主要アプリに対しても専用プラグインを提供しています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">アプリとダイアログ種別</th><th style="text-align:left;">インライン検索</th><th style="text-align:left;">クイックナビゲーション操作</th><th style="text-align:left;">備考</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>WPS Office</strong> 開く/保存ダイアログ</td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンをクリック</td><td style="text-align:left;">WPS Writer、Spreadsheets、Presentation、PDF を網羅</td></tr><tr><td style="text-align:left;"><strong>WinRAR</strong> 解凍ダイアログ</td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンをクリック</td><td style="text-align:left;">解凍先フォルダーを素早く指定</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> 解凍ダイアログ</td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンをクリック</td><td style="text-align:left;">解凍先の出力フォルダーを即座に指定</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> ファイル追加ダイアログ</td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンをクリック</td><td style="text-align:left;">アーカイブに追加するファイルを素早く選択</td></tr><tr><td style="text-align:left;"><strong>AutoCAD</strong> 開く/保存ダイアログ</td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンをクリック</td><td style="text-align:left;">設計図面ファイルの素早い保管と呼び出しに最適化</td></tr></tbody></table><p>各プラグインはウィンドウの内部コントロール構造とハンドル階層を直接認識して動作するため、言語パックや細かな UI の違いに左右されません。</p>',20)])])}const h=e(d,[["render",r]]);export{x as __pageData,h as default};
